{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Mix 80% baseline BCE loss with 20% pairwise softplus ranking loss on the existing sampled pairs at valid positions. This adds direct ranking pressure while preserving sampling, architecture, inference, and training settings for all four category models.",
      "edits": [
        {
          "find": "            loss = bce_criterion(pos_logits[indices], pos_labels)\n            loss = loss + bce_criterion(neg_logits[indices], neg_labels)",
          "replace": "            prediction_loss = bce_criterion(pos_logits[indices], pos_labels)\n            prediction_loss = prediction_loss + bce_criterion(neg_logits[indices], neg_labels)\n            ranking_loss = torch.nn.functional.softplus(neg_logits[indices] - pos_logits[indices]).mean()\n            loss = 0.8 * prediction_loss + 0.2 * ranking_loss"
        }
      ]
    }
  ],
  "change_summary": "Apply the requested BCE/ranking objective blend to each category's single SASRec model. Predictor and checkpoint formats remain compatible."
}
